(1, 'surgery.authorized', 'email', 1, 8, 'admin@metallive.com.ar', 'Cirugía autorizada para asignar: CX-000008', '<!doctype html>\n<html lang="es">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cirugía autorizada para asignar: CX-000008</title></head>\n<body style="margin:0;padding:0;background:#f2f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#0f1e33">\n  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f5f9;padding:24px 12px">\n    <tr><td align="center">\n      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">\n        <tr><td style="background:#0b1b36;padding:18px 24px;color:#ffffff;font-size:18px;font-weight:700;letter-spacing:.5px">\n          <span style="color:#0794fb">●</span> METAL LIVE\n        </td></tr>\n        <tr><td style="padding:24px">\n          <h1 style="margin:0 0 12px;font-size:19px;line-height:1.3">Cirugía autorizada para asignar: CX-000008</h1>\n          <p style="margin:0 0 18px;font-size:15px;line-height:1.5;color:#334155">La cirugía fue autorizada y está lista para asignar material, caja, instrumentadora y chofer.</p>\n                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px">\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Cirugía</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">CX-000008 · Fijación de fractura de tobillo</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Fecha</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">—</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Institución</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">Hospital Italiano</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Cliente</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">IOMA</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Médico</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">Fernández, Julián</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Paciente</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">Gutiérrez, Andrea</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Vendedor</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">Sofía Vendedora</td>\n              </tr>\n                      </table>\n                                <p style="margin:24px 0 8px"><a href="http://localhost:8080/admin/cirugias/8" style="display:inline-block;background:#0794fb;color:#ffffff;text-decoration:none;font-weight:700;padding:12px 22px;border-radius:8px">Asignar</a></p>\n                            </td></tr>\n        <tr><td style="padding:14px 24px;background:#f8fafc;font-size:12px;color:#94a3b8">Aviso automático del sistema de gestión de cirugías de Metal Live.</td></tr>\n      </table>\n    </td></tr>\n  </table>\n</body>\n</html>\n', 'enviado', 1, NULL, '2026-11-12 15:34:53', '2026-11-12 15:34:53'),
(2, 'surgery.authorized', 'email', 1, 9, 'admin@metallive.com.ar', 'Cirugía autorizada para asignar: CX-000009', '<!doctype html>\n<html lang="es">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cirugía autorizada para asignar: CX-000009</title></head>\n<body style="margin:0;padding:0;background:#f2f5f9;font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#0f1e33">\n  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f5f9;padding:24px 12px">\n    <tr><td align="center">\n      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">\n        <tr><td style="background:#0b1b36;padding:18px 24px;color:#ffffff;font-size:18px;font-weight:700;letter-spacing:.5px">\n          <span style="color:#0794fb">●</span> METAL LIVE\n        </td></tr>\n        <tr><td style="padding:24px">\n          <h1 style="margin:0 0 12px;font-size:19px;line-height:1.3">Cirugía autorizada para asignar: CX-000009</h1>\n          <p style="margin:0 0 18px;font-size:15px;line-height:1.5;color:#334155">La cirugía fue autorizada y está lista para asignar material, caja, instrumentadora y chofer.</p>\n                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px">\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Cirugía</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">CX-000009 · Artrodesis lumbar L4-L5</td>\n              </tr>\n                          <tr>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;color:#64748b;width:38%;vertical-align:top">Fecha</td>\n                <td style="padding:8px 10px;border-bottom:1px solid #e6ebf2;font-weight:600">—</td>\n        